/// <summary>
/// This method is to control enable/disable of bulk updates
/// CB715_TransferOrderExtract - PS
/// </summary>
public void selectionChanged()
{
    super();
    int recordsCount = InventTransferTable_ds.recordsMarked().lastIndex();
    
    METransferOrderExtractScreenModifyDialog.enabled(true);
    UpdateStatusFormButtonControl.enabled(true);
    if (recordsCount < 1)
    {
        METransferOrderExtractScreenModifyDialog.enabled(false);
        UpdateStatusFormButtonControl.enabled(false);
    }
}

/// <summary>
/// This is an edit method
/// </summary>
/// <param name = "_set">Set</param>
/// <param name = "_inventTransferTable">SalesTable</param>
/// <param name = "_markTrans">MarkTrans</param>
/// <returns>EditValue</returns>
[SysClientCacheDataMethodAttribute(true)]
public edit NoYes editMarkTrans(boolean _set, InventTransferTable _inventTransferTable, NoYes _markTrans)
{
    if (_set)
    {
        if(!_markTrans)
        {
            if (selectionMap.exists(_inventTransferTable.RecId))
            {
                selectionMap.remove(_inventTransferTable.RecId);
            }
        }
        else
        {
            selectionMap.insert(_inventTransferTable.RecId, _inventTransferTable.TransferId);
        }
    }
    return selectionMap.exists(_inventTransferTable.RecId);
}

