        /// <summary>
        /// This method is to update the status
        /// CB715_TransferOrderExtract - PS
        /// </summary>
        public void clicked()
        {
            super();

            InventTransferTable     invTransferTbl;
            container               invTransferTblIdCon;
            Map                     map = selectionMap;
            MapEnumerator           mapEnumerator = map.getEnumerator();
         
            while (mapEnumerator.moveNext())
            {
                invTransferTbl = InventTransferTable::find(mapEnumerator.currentValue());

                //Write the code here
                if (!conFind(invTransferTblIdCon, invTransferTbl.TransferId))
                {
                    METInventTransferTableExt   transExtTbl = invTransferTbl.metInventTransferTableExt();
                    
                    this.updateOrderExtractScreenRec(invTransferTbl, transExtTbl);
                    invTransferTblIdCon += invTransferTbl.TransferId;
                }
            }
            InventTransferTable_ds.executeQuery();
        }

        /// <summary>
        /// Updates <c>InventTransferTable</c> with parameters.
        /// CB715_TransferOrderExtract - PS
        /// </summary>
        /// <param name = "_inventTransferTableExt">InventTransferTable buffer</param>
        private void updateOrderExtractScreenRec(InventTransferTable        _inventTransferTable, METInventTransferTableExt _inventTransferTableExt)
        {
            #OCCRetryCount

            InventTransferLine                  inventTransferLine;
            METInventTransferLine               metInventTransferLine;
            boolean                             updateInventTransferTableExt;
            try
            {
                ttsbegin;

                _inventTransferTable.selectForUpdate(true);
                _inventTransferTableExt.selectForUpdate(true);
  
                if (_inventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
                {
                    _inventTransferTableExt.OrderExtractStatus =  METOrderExtractStatus::Open;
                    updateInventTransferTableExt = true;
                }
                else if (_inventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::Open)
                {
                    updateInventTransferTableExt = false;
                    if (!_inventTransferTableExt.Route || !_inventTransferTableExt.RouteStopNum)
                    {
                        updateInventTransferTableExt = checkFailed(strFmt("@MET:SOExtractRouteWarning", inventTransferTable.TransferId));
                    }
                    else
                    {

                        //Check if atleast one salesline has reserved quantity;
                        while select OrderExtractStatus from metInventTransferLine
                            join inventTransferLine
                            where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
                            && inventTransferLine.TransferId == inventTransferTable.TransferId
                            && metInventTransferLine.OrderExtractStatus != METOrderExtractStatus::Extracted
                        {
                            updateInventTransferTableExt = true;
                            break;
                        }

                    }
                    if (updateInventTransferTableExt)
                    {
                        _inventTransferTableExt.OrderExtractStatus =  METOrderExtractStatus::ReadyForExtract;
                    }
                }
                if (updateInventTransferTableExt)
                {
                    _inventTransferTableExt.update();
                    _inventTransferTableExt.reread();

                    update_recordset metInventTransferLine
                        setting OrderExtractStatus = _inventTransferTableExt.OrderExtractStatus
                            where metInventTransferLine.OrderExtractStatus != METOrderExtractStatus::Extracted
                        exists join inventTransferLine
                            where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
                                && inventTransferLine.TransferId == _inventTransferTable.TransferId;

                    info(StrFmt("@MET:Changes", _inventTransferTable.TransferId));
                }
                ttscommit;
            }
            catch (Exception::Error)
            {
                error("@MET:METBulkUpdateError");
            }

            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }

        }

